pragma cashscript ^0.13.0;

// A single-use NFT coupon. The NFT is burned on redemption because this
// transaction creates no continuing token output for its category.
contract CouponRedeem(
    pubkey businessPk,
    bool transferable,
    bytes32 couponCategory,
    int rewardValue
) {
    function redeem(sig businessSig, pubkey redeemerPk, sig redeemerSig) {
        require(checkSig(businessSig, businessPk));
        require(checkSig(redeemerSig, redeemerPk));

        // Input 0 is the coupon NFT presented by the customer.
        require(tx.inputs[0].tokenCategory == couponCategory);

        // Non-transferable coupons store the original recipient public key in
        // the NFT commitment, making ownership binding part of the token itself.
        if (!transferable) {
            require(tx.inputs[0].nftCommitment == redeemerPk);
        }

        // Output 0 pays the reward; output 1 returns BCH change to merchant.
        // There is no token output, so the coupon NFT is consumed forever.
        require(tx.outputs.length == 2);
        require(tx.outputs[0].value == rewardValue);
    }
}
